import fs from'node:fs';import path from'node:path';import{createHash}from'node:crypto';import{performance}from'node:perf_hooks';import{journalLines}from'../live-paper/journal-lines.mjs';import{sealedEnd}from'./replay-dual-no-timelapse-20261005.mjs';import{applyBookPublication,createBookPublicationState}from'../live-paper/book-publication-v2.mjs';import{digest}from'../live-paper/model.mjs';import{assertSettlementPortfolioState}from'../live-paper/settlement-portfolio-paper-v2.mjs';import{fillMarkout}from'../live-paper/fill-markout.mjs';
const rt=process.env.LOCALAPPDATA+'/SigTradingCup/paper-runtime',cohort='kansas-horizon-portfolio-20261005-v2',dir=path.join(rt,'settlement-portfolio-v2-cohorts',cohort),bank=JSON.parse(fs.readFileSync(dir+'/bank.json')),walletFile=dir+'/journal.jsonl',walletEnd=sealedEnd(walletFile),walletHash=createHash('sha256');let seq=0,prev='',last;for(const line of journalLines(walletFile,{endByte:walletEnd})){walletHash.update(line+'\n');const r=JSON.parse(line),{hash,...body}=r;if(r.sequence!==++seq||r.previous!==prev||createHash('sha256').update(JSON.stringify(body)).digest('hex')!==hash)throw Error('WALLET_CHAIN');assertSettlementPortfolioState(r.state.paper,bank);prev=hash;last=r;}
const fills=new Map();for(const[latency,w]of Object.entries(last.state.paper.wallets))for(const f of w.fills)if(f.action==='buy'){const key=f.marketId+':'+f.intentId+':'+f.at+':'+f.price;const p=fills.get(key)||{fill:f,latencyCases:[]};p.latencyCases.push(latency);fills.set(key,p);}
const sourceFile=rt+'/public-books.jsonl',end=sealedEnd(sourceFile),raw=createHash('sha256'),started=performance.now();let pub=createBookPublicationState(bank.universe);const entries=new Map(),later=[];const marketIds=new Set([...fills.values()].map(x=>x.fill.marketId));for(const line of journalLines(sourceFile,{endByte:end})){raw.update(line+'\n');const r=JSON.parse(line);pub=applyBookPublication(pub,r);if(r.kind==='book'&&marketIds.has(r.payload.book.marketId)){later.push(r);for(const p of fills.values())if(r.sequence===p.fill.sourceSequence)entries.set(p.fill.sourceSequence,r);}}
const results=[...fills.values()].map(p=>({...fillMarkout(p.fill,entries.get(p.fill.sourceSequence),later,{throughAt:pub.lastAt}),correlatedLatencyCases:p.latencyCases}));const out={schemaVersion:1,at:new Date().toISOString(),cohort,bankHash:digest(bank),wallet:{prefixBytes:walletEnd,sha256:walletHash.digest('hex'),sequence:seq,tailHash:prev},source:{prefixBytes:end,sha256:raw.digest('hex'),sequence:pub.sequence,tailHash:pub.hash,throughAt:pub.lastAt},wallMs:performance.now()-started,distinctPurchaseOpportunities:results.length,results,fees:'0.000000',sourceQuotesVerified:true,originalJournalUnchanged:true,accountRequests:0,simulatedSales:0,realizedProfitFromDiagnostic:null,profitabilityEstablished:false,limitations:['Markouts are later observed depth-aware quote proceeds, not accepted sale orders.','Source gaps and unknown later liquidity are censored, never forward-filled.','One-tick assumptions are explicit modeling stress, not platform fees.','Latency variants of the same opportunity are deduplicated; a tiny sample does not establish an edge.']};fs.writeFileSync('data/portfolio-fill-markouts-20261006.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify({opportunities:results.length,wallMs:out.wallMs,results}));
